custom_css:
/* 幽夜月澜（幽夜青碧·夜间版）
月夜蓝银 + 烛金点缀；顶栏为 SillyTavern 原版图标
感谢分享代码教程的老师们
*/

/* 1自定义字体 */
@import url("https://fontsapi.zeoseven.com/467/main/result.css");

@font-face {
    font-family: 'CustomInkFont';
    src: url('https://files.catbox.moe/gtf0xv.otf') format('opentype');
    font-weight: normal;
    font-style: normal;
    font-display: swap;
}

@font-face {
    font-family: 'MyInputFont';
    src: url('https://files.catbox.moe/n6mb7l.otf');
}

body,
button,
input,
textarea,
select {
    font-family: "NanoOldSong-A", "思源宋体", "Noto Serif SC", serif !important;
    font-weight: normal;
}

/* 2. 界面全局背景 */
.drawer-content {
  background:
    radial-gradient(ellipse 120% 60% at 50% -10%, rgba(120, 140, 185, 0.12), transparent 60%),
    linear-gradient(180deg, #0B1226 0%, #060A18 45%, #03050C 100%) !important;
}

/* 全局控制面板 */
:root {
    --全局-背景色: #04060D;
    --全局-边框色: #16203A;
    --全局-阴影色: rgba(0,0,0,0.5);
    --全局-强调色: rgba(120,140,185,0.25);

    --顶栏-高度: 32px;
    --顶栏-背景色: #060A16;
    --顶栏-内边距: 0 5px;
    --聊天区-顶部内边距: 36px;

    --书页-标题: '母羊的\A眼睛';
    --书页-副标题: '文/一颗菩提果 ';

    --书页-标题-上: 4cqw;  /* 主标题 */
    --书页-标题-右: 9cqw; 
    --书页-标题-大小: 3.1em;

    --书页-副标-上: 5cqw; /*  副标题*/
    --书页-副标-右: 42cqw; 
    --书页-副标-大小: 1.1em;

    --书页-顶部留白: 45cqw; 
    --书页-左右留白: 5cqw;
    --书页-分隔线色: rgba(205, 217, 236, 0.1);

    --页眉-字号: 3cqw; 
    --页眉-字色: #8B9AB8;
    --页眉-前缀色: #5A688A;

    --水印-图片: url('https://iili.io/BtPTljI.png');
    --水印-上: 0px;
    --水印-右: 230px;
    --水印-宽: 150px;
    --水印-高: 150px;
    --水印-透明度: 0.4;
    --水印-羽化: 25%;

    --楼层-上: 48cqw; 
    --楼层-右: 12cqw; 
    --楼层-前缀: '被母羊凝视第';
    --楼层-后缀: '次';

    --字数-上: 45cqw;
    --字数-右: 21cqw;
    --字数-前缀: '假性温顺';
    --字数-后缀: '';

    --计时-上: 42cqw;
    --计时-右: 24cqw;
    --计时-前缀: '沉默裂痕';
    --计时-后缀: '';

    --名字-字号: 1.1em;
    --名字-前缀: '◈ ';  
    --名字-颜色: #C9B691;
    --时间-字号: 0.75em;
    --时间-前缀: ''; 
    --时间-颜色: #5A688A;
    --时间-间距: 6px;

    --输入栏-发送: "春";
    --输入栏-选项: "夏";
    --输入栏-插件: "秋";
    --输入栏-停止: "冬";

}

.mes {
    container-type: inline-size;
}

/* 3. 顶部导航栏字体（@墨千尾老师拼好码） */
#top-bar,
#top-settings-holder,
.top-bar,
.topBar {
    height: var(--顶栏-高度) !important;
    background-color: var(--顶栏-背景色) !important;
    border-bottom: 1px solid #16203A !important;
    box-shadow: 0 1px 3px var(--全局-阴影色) !important;
    padding: var(--顶栏-内边距) !important;
}

#chat {
    padding-top: var(--聊天区-顶部内边距) !important;
}

/* 4.1 消息容器完整样式 */
.mes {
    position: relative !important;
    background-color: #04060D !important;
    transform: none !important;
    width: 100% !important;
    margin: 0 0 20px 0 !important;
    padding-top: var(--书页-顶部留白) !important;
    padding-bottom: 30px !important;
    padding-left: var(--书页-左右留白) !important;
    padding-right: var(--书页-左右留白) !important;
    box-sizing: border-box !important;
    border: none !important;
    border-top: 1px dotted var(--书页-分隔线色) !important;
    box-shadow: none !important;
}
#chat .mes:first-of-type { border-top: none !important; }

/* 4.2 mesAvatarWrapper 作为标题画布 */
.mes .mesAvatarWrapper {
    position: absolute !important;
    top: 0 !important;
    left: 0 !important;
    width: 100% !important;
    height: 100% !important;
    background: transparent !important;
    pointer-events: none !important;
    z-index: 2 !important;
    border: none !important;
    transform: none !important;
}
.mes .mesAvatarWrapper .avatar { display: none !important; }

/* 4.3 标题伪元素 */
.mes .mesAvatarWrapper::before,
.mes .mesAvatarWrapper::after {
    position: absolute;
    writing-mode: vertical-rl;
    text-orientation: mixed;
    white-space: pre;
}
.mes .mesAvatarWrapper::before {
    content: var(--书页-标题);
    top: var(--书页-标题-上);
    right: var(--书页-标题-右);
    font-size: var(--书页-标题-大小);
    font-weight: 900;
    color: #CDD9EC;
    letter-spacing: 0.1em;
    text-shadow: 0 0 5px rgba(205, 217, 236, 0.15);
}
.mes .mesAvatarWrapper::after {
    content: var(--书页-副标题);
    top: var(--书页-副标-上);
    right: var(--书页-副标-右);
    font-size: var(--书页-副标-大小);
    color: #7A8AA8;
}

/* 4.4 页眉信息栏 */
.mes .mesIDDisplay,
.mes .tokenCounterDisplay,
.mes .mes_timer {
    position: absolute !important;
    z-index: 3;
    font-size: var(--页眉-字号) !important;
    color: var(--页眉-字色) !important;
    text-align: right !important;
    font-weight: 400 !important;
    white-space: nowrap;
    opacity: 0.9;
    transform: none !important;
    margin: 0 !important;
    padding: 0 !important;
}
.mes .mesIDDisplay::before,
.mes .mesIDDisplay::after,
.mes .tokenCounterDisplay::before,
.mes .tokenCounterDisplay::after,
.mes .mes_timer::before,
.mes .mes_timer::after {
    color: var(--页眉-前缀色);
}

.mes .mesIDDisplay         { top: var(--楼层-上) !important; right: var(--楼层-右) !important; }
.mes .mesIDDisplay::before { content: var(--楼层-前缀); }
.mes .mesIDDisplay::after  { content: var(--楼层-后缀); }

.mes .tokenCounterDisplay         { top: var(--字数-上) !important; right: var(--字数-右) !important; }
.mes .tokenCounterDisplay::before { content: var(--字数-前缀); }
.mes .tokenCounterDisplay::after  { content: var(--字数-后缀); }

.mes .mes_timer         { top: var(--计时-上) !important; right: var(--计时-右) !important; }
.mes .mes_timer::before { content: var(--计时-前缀); }
.mes .mes_timer::after  { content: var(--计时-后缀); }

/* 水印装饰图 */
.mes::after {
    content: '';
    position: absolute;
    top: var(--水印-上);
    right: var(--水印-右);
    width: var(--水印-宽);
    height: var(--水印-高);
    background-image: var(--水印-图片);
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    opacity: var(--水印-透明度);
    pointer-events: none;
    z-index: 0;
    filter: none !important;
    -webkit-mask-image: radial-gradient(circle, black calc(100% - var(--水印-羽化)), transparent 100%);
    mask-image: radial-gradient(circle, black calc(100% - var(--水印-羽化)), transparent 100%);
}

/* --- 5. 消息内容区 --- */
.mes .mes_block {
    position: relative !important;
    z-index: 1;
    background: none !important;
    border: none !important;
    box-shadow: none !important;
    padding: 0 !important;
    margin: 0 !important;
    transform: none !important;
}

/* 名字+时间戳竖排 */
.mes .mes_block .flex-container.alignItemsBaseline {
    display: flex !important;
    flex-direction: column !important;
    align-items: flex-start !important;
    gap: var(--时间-间距) !important;
    margin-bottom: 0.8em !important;
    position: static !important;
    transform: none !important;
}

.mes .mes_block .flex-container.alignItemsBaseline span.name_text {
    font-size: var(--名字-字号) !important;
    color: var(--名字-颜色) !important;
    font-weight: 600 !important;
    letter-spacing: 0.05em;
    line-height: 1.2 !important;
}
.mes .mes_block .flex-container.alignItemsBaseline span.name_text::before {
    content: var(--名字-前缀);
    opacity: 0.5;
    font-weight: 400;
}

.mes .mes_block .flex-container.alignItemsBaseline small.timestamp {
    font-size: var(--时间-字号) !important;
    color: var(--时间-颜色) !important;
    font-weight: 400 !important;
    line-height: 1.2 !important;
    opacity: 0.85;
}
.mes .mes_block .flex-container.alignItemsBaseline small.timestamp::before {
    content: var(--时间-前缀);
    opacity: 0.6;
}

.mes .mes_text {
    width: 100% !important;
    max-width: 100% !important;
    box-sizing: border-box !important;
    text-align: justify !important;
    padding-top: 1.5em !important;
    padding-left: 0 !important;
    padding-right: 0 !important;
    line-height: 1.8 !important;
    color: #CDD9EC !important;
}

/* --- 6. 文集风格文本样式--- */
/* 1. 斜体 */
.mes_text em, .mes_text i {
    font-style: normal !important;
    background: none !important;
    border: none !important;
    text-emphasis-style: '•'; -webkit-text-emphasis-style: '•';
    text-emphasis-position: under; -webkit-text-emphasis-position: under;
    color: inherit !important;
    transition: all 0.1s ease;
}

/* 2. 引用*/
.mes_text q {
    background: none !important;
    border: none !important;
    color: #ffffff !important;   /* 纯白高亮 */
    font-weight: 500 !important;
    quotes: none !important;
}
.mes_text q::before {
    content: '「' !important;
    margin-right: 0.15em;
}
.mes_text q::after {
    content: '」' !important;
    margin-left: 0.15em;
}

/* 3. 加粗 */
.mes_text strong {
    font-weight: 800 !important;
    letter-spacing: 0.02em;
    color: #ffffff !important;
    background: none !important;
    text-shadow: none !important;
    box-shadow: none !important;
    display: inline-block;
}

/* 4. 单行代码块  */
.mes_text code {
    font-family: 'KaiTi', 'STKaiti', 'SimSun', serif !important;
    background-color: rgba(16, 22, 38, 0.5) !important;
    border: 1px dashed rgba(205, 217, 236, 0.3) !important;
    color: #9DB3D8 !important;
    border-radius: 3px !important;
    padding: 2px 6px !important;
    font-size: 0.92em !important;
}

/* 5. 引用块 */
.mes_text blockquote {
    background: transparent !important;
    border: none !important;
    border-left: 2px solid rgba(205, 217, 236, 0.3) !important;
    margin: 1.2em 0 1.2em 1.2em !important;
    padding: 0.2em 0 0.2em 1.2em !important;
    color: #8B9AB8 !important;
    font-style: normal !important;
}

/* 6.代码块*/
.mes_text pre {
    background-color: rgba(10, 14, 26, 0.5) !important;
    border: 1px solid rgba(205, 217, 236, 0.15) !important;
    border-left: 3px solid rgba(205, 217, 236, 0.3) !important;
    padding: 1em 1.2em !important;
    margin: 1.2em 0 !important;
    font-family: 'KaiTi', 'STKaiti', 'SimSun', monospace !important;
    font-size: 0.92em !important;
    line-height: 1.5 !important;
    color: #9DB3D8 !important;
    overflow-x: auto !important;
    white-space: pre-wrap !important;
    box-shadow: none !important;
}
.mes_text pre code {
    background: none !important;
    border: none !important;
    padding: 0 !important;
    font-size: inherit !important;
    color: inherit !important;
}

/* --- 7. UI标题栏  --- */

:root {
    --ink-black: #CDD9EC;
    --ink-dark:  #7A8AA8;
    --ink-light: rgba(205, 217, 236, 0.08);
}

.inline-drawer-header,
#extensions_settings .inline-drawer-toggle.inline-drawer-header,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header,
#user-settings-block h4,
.standoutHeader {
    padding: 6px 17px !important;
    min-height: 30px !important;
    line-height: 1.5 !important;
    font-size: 15px !important;
    font-weight: bold !important;
    letter-spacing: 0.05em;
    font-family: var(--main-font), "KaiTi", serif !important;
    border-radius: 0 !important;
    background: linear-gradient(to right, rgba(205, 217, 236, 0.05) 0%, transparent 100%) !important;
    border: none !important;
    border-bottom: 1px solid rgba(205, 217, 236, 0.15) !important;
    border-left: 4px solid var(--ink-dark) !important;
    color: var(--ink-dark) !important;
    text-shadow: none !important;
    transform: none !important;
    transition: all 0.3s ease !important;
    position: relative;
    overflow: hidden !important;
    z-index: 1;
}

.inline-drawer-header::before,
#user-settings-block h4::before,
.standoutHeader::before {
    display: inline-block !important;
    margin-right: 8px;
    font-size: 12px;
    opacity: 0.5;
    color: var(--ink-dark) !important;
}

.inline-drawer-header:hover,
#user-settings-block h4:hover,
.standoutHeader:hover {
    background-color: var(--ink-light) !important;
    color: var(--ink-black) !important;
    border-left: 6px solid var(--ink-black) !important;
    padding-left: 20px !important;
    box-shadow: none !important;
}

.inline-drawer-header.open,
.standoutHeader.open {
    background-color: rgba(205, 217, 236, 0.1) !important;
    color: var(--ink-black) !important;
    border-left-color: var(--ink-black) !important;
    border-bottom: 1px solid rgba(205, 217, 236, 0.4) !important;
}

/* --- 8-9. 输入框 / 下拉框 / Textarea --- */
.drawer-content select,
.drawer-content input[type="text"],
.drawer-content input[type="number"],
.drawer-content textarea,
textarea {
    -webkit-appearance: none !important;
    appearance: none !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    background-color: rgba(10, 14, 26, 0.5) !important;
    border: 1px solid rgba(205, 217, 236, 0.2) !important;
    color: #CDD9EC !important;
    font-family: var(--main-font) !important;
    font-size: calc(var(--mainFontSize) * 0.95) !important;
    padding: 8px 10px !important;
    transition: all 0.3s ease !important;
}

textarea {
    width: 100%;
    resize: vertical;
    display: block;
    outline: none;
    max-height: 80vh;
    background-color: #04060D !important;
    background-image: none !important;
    padding: 15px !important;
    border: 1px solid rgba(205, 217, 236, 0.2) !important;
    color: #CDD9EC !important;
}

.drawer-content select {
    cursor: pointer;
    padding-right: 30px !important;
    background-image: url('data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="%23AEBDD8" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"></polyline></svg>') !important;
    background-repeat: no-repeat !important;
    background-position: right 8px center !important;
    background-size: 14px !important;
}

.drawer-content select option {
    background-color: #060A16 !important;
    color: #CDD9EC !important;
}

/* 滚动条 */
textarea::-webkit-scrollbar { width: 8px; }
textarea::-webkit-scrollbar-track { background: transparent; }
textarea::-webkit-scrollbar-thumb {
    background-color: rgba(205, 217, 236, 0.2);
    border-radius: 0;
    border: 2px solid #04060D;
}
textarea::-webkit-scrollbar-thumb:hover { background-color: rgba(205, 217, 236, 0.5); }

/* --- 10. 复选框 --- */
.drawer-content input[type="checkbox"] {
    -webkit-appearance: none; appearance: none;
    position: relative; cursor: pointer;
    width: 18px !important; height: 18px !important;
    background-color: transparent !important;
    border: 1.5px solid rgba(205, 217, 236, 0.4) !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    transition: all 0.3s ease;
    vertical-align: middle; margin-top: -2px;
}
.drawer-content input[type="checkbox"]:hover {
    border-color: #ffffff !important;
}
.drawer-content input[type="checkbox"]:checked {
    border-color: #CDD9EC !important;
}

.drawer-content input[type="checkbox"]::before { display: none !important; }
.drawer-content input[type="checkbox"]::before { display: none !important; }
.drawer-content input[type="checkbox"]::after {
    content: '✓';
    position: absolute; top: 50%; left: 50%;
    font-family: var(--main-font);
    font-size: 20px; font-weight: bold;
    color: #CDD9EC !important;
    line-height: 1;
    opacity: 0;
    transform: translate(-50%, -50%) scale(0.5);
    transition: all 0.25s cubic-bezier(0.34, 1.56, 0.64, 1);
}
.drawer-content input[type="checkbox"]:checked::after {
    opacity: 1; transform: translate(-50%, -50%) scale(1);
}
.drawer-content input[type="checkbox"]:checked {
    background-color: rgba(205, 217, 236, 0.1) !important;
}

/* --- 11. 滑块 --- */
.drawer-content .neo-range-slider,
.drawer-content input[type="range"],
input[type="range"] {
    -webkit-appearance: none !important; appearance: none !important;
    background: transparent !important;
    filter: none !important; box-shadow: none !important;
    padding: 0 !important; width: 100%;
}

input[type="range"]::-webkit-slider-runnable-track {
    width: 100%; height: 4px; cursor: pointer;
    background: rgba(0, 0, 0, 0.15) !important;
    border-radius: 0; border: none !important; box-shadow: none !important;
}

input[type="range"]::-webkit-slider-thumb {
    -webkit-appearance: none;
    border: none !important;
    background: url('https://iili.io/BtPTljI.png') center / contain no-repeat !important;
    box-shadow: none !important;
    width: 35px; height: 35px; margin-top: -14px !important;
    cursor: pointer;
    transition: transform 0.2s ease, filter 0.2s ease;
    filter: drop-shadow(0 1px 2px rgba(0,0,0,0.2));
}

/* 合并 hover + active */
input[type="range"]::-webkit-slider-thumb:hover,
input[type="range"]::-webkit-slider-thumb:active {
    transform: scale(1.15);
    filter: drop-shadow(0 0 5px rgba(0,0,0,0.6));
}

/* 12.底部输入框 */
#send_form:hover {
    border-color: rgba(205, 217, 236, 0.3) !important;
    box-shadow: 0 6px 20px rgba(0, 0, 0, 0.8) !important;
}

#send_form {
    display: flex !important;
    flex-direction: column;
    width: 100% !important;
    max-width: 520px !important;
    margin: 0 auto 2px auto !important;
    padding: 4px 12px !important;
    gap: 0;
    border-radius: 2px !important;
    position: relative;
    z-index: 10;
    background: rgba(6, 10, 20, 0.95) !important;
    backdrop-filter: blur(5px);
    -webkit-backdrop-filter: blur(5px);
    border: 1px solid rgba(205, 217, 236, 0.15) !important;
    box-shadow: 0 4px 15px rgba(0, 0, 0, 0.6) !important;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

#send_form::before { display: none !important; }
#send_form #mes_stop i { display: none !important; }

#send_textarea {
    background: transparent !important;
    border: none !important;
    box-shadow: none !important;
    padding: 2px 0 !important;
    font-family: 'MyInputFont', "KaiTi", "STKaiti", serif !important;
    color: #CDD9EC !important;
    font-size: 14px !important;
    line-height: 1.4 !important;
    flex: 1;
    min-height: 32px !important;
    transition: height 0s !important;
}

#options_button,
#extensionsMenuButton,
#send_but,
#mes_stop {
    flex-shrink: 0;
    width: 34px !important;
    height: 34px !important;
    border-radius: 2px !important;
    font-size: 0 !important;
    cursor: pointer;
    background: transparent !important;
    background-image: none !important;
    border: 0.5px dashed rgba(205, 217, 236, 0.25) !important;
    box-shadow: none !important;
    opacity: 0.75;
    transition: all 0.2s ease !important;
    filter: none !important;
    position: relative;
}

#options_button:hover,
#extensionsMenuButton:hover,
#send_but:hover,
#mes_stop:hover {
    opacity: 1;
    background-color: #16203A !important;
    border-color: rgba(205, 217, 236, 0.6) !important;
    transform: translateY(-1px);
}

#options_button::after,
#extensionsMenuButton::after,
#send_but::after,
#mes_stop::after {
    font-family: 'CustomInkFont', "KaiTi", "STKaiti", serif !important;
    font-size: 16px;
    font-weight: normal;
    color: #CDD9EC;
    display: flex;
    align-items: center;
    justify-content: center;
    width: 100%;
    height: 100%;
    position: absolute;
    top: 0; left: 0;
}

#options_button::after       { content: var(--输入栏-选项); }
#extensionsMenuButton::after { content: var(--输入栏-插件); }
#send_but::after             { content: var(--输入栏-发送); }
#mes_stop::after             { content: var(--输入栏-停止); }

#send_form .form_button:hover {
